INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(36511, 'Mark 1:32', 'Mark', 1, 32, 'کله چې لمر پرېوت او ماښام شو، نو خلکو خپل ټول ناروغان او هغه خلک چې پېریانو نیولي وو هغه ته راوستل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark1_verse_32.mp3', '', 1761754199, 1761754199),
(36512, 'Mark 1:33', 'Mark', 1, 33, 'د ښار ټول خلک د هغه کور مخې ته راټول شول.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark1_verse_33.mp3', '', 1761754199, 1761754199),
(36513, 'Mark 1:34', 'Mark', 1, 34, 'عیسی ډېر ناروغان چې په ډول ډول ناروغیو اخته وو روغ کړل او ډېر پېریان یې وویستل. عیسی پېریان خبرو ته پرېنښودل، ځکه چې هغوی پوهېدل چې هغه څوک دی. عیسی په جلیل کې وعظ کوي (لوقا ۴‏:‌۴۲‌‏-‌۴۴)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark1_verse_34.mp3', '', 1761754199, 1761754199),
(36514, 'Mark 1:35', 'Mark', 1, 35, 'سهار وختي چې لا تیاره وه، عیسی له خوبه راپاڅېد، د کور نه ووت او یو ګوښه ځای ته لاړ او هلته یې دعا کوله.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark1_verse_35.mp3', '', 1761754199, 1761754199),
(36515, 'Mark 1:36', 'Mark', 1, 36, 'نو شمعون او د هغه ملګري لاړل چې هغه ولټوي،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark1_verse_36.mp3', '', 1761754199, 1761754199),
(36516, 'Mark 1:37', 'Mark', 1, 37, 'او چې کله یې هغه پیدا کړ، نو ورته ویې ویل: «ټول خلک تا لټوي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark1_verse_37.mp3', '', 1761754199, 1761754199),
(36517, 'Mark 1:38', 'Mark', 1, 38, 'عیسی هغوی ته وویل: «راځئ چې شاوخوا کلیو ته لاړ شو ترڅو هلته هم خپل پیغام ورسوم، ځکه چې زه د همدې کار دپاره راغلی یم.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark1_verse_38.mp3', '', 1761754199, 1761754199),
(36518, 'Mark 1:39', 'Mark', 1, 39, 'عیسی په ټول جلیل کې ګرځېده، د هغوی په کنیسو کې یې وعظ کاوه او پېریان یې ویستل. عیسی یو جذامي ته شفا ورکوي (متي ۸‏:‌۱‌‏-‌۴ او لوقا ۵‏:‌۱۲‌‏-‌۱۶)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark1_verse_39.mp3', '', 1761754199, 1761754199),
(36519, 'Mark 1:40', 'Mark', 1, 40, 'یو سړی چې د جذام په ناروغۍ اخته ؤ، عیسی ته راغی، د هغه په مخکې په ګونډو شو او زاري یې ورته وکړه: «که چېرې ته وغواړې، نو کولای شې چې ما پاک او روغ کړې.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark1_verse_40.mp3', '', 1761754199, 1761754199),
(36520, 'Mark 1:41', 'Mark', 1, 41, 'د عیسی زړه ورباندې وسوځېد، خپل لاس یې وراوږد کړ او په هغه باندې یې کېښود او ورته ویې ویل: «هو، زه غواړم، پاک او روغ شه.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark1_verse_41.mp3', '', 1761754199, 1761754199),
(36521, 'Mark 1:42', 'Mark', 1, 42, 'نو سمدلاسه د هغه ‎څخه د جذام ناروغي لېرې شوه او هغه پاک شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark1_verse_42.mp3', '', 1761754199, 1761754199),
(36522, 'Mark 1:43', 'Mark', 1, 43, 'بیا عیسی هغه زر رخصت کړ او سخت خبرداری یې ورکړ', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark1_verse_43.mp3', '', 1761754199, 1761754199),
(36523, 'Mark 1:44', 'Mark', 1, 44, 'او ورته ویې ویل: «ګوره، په دې هکله هېچا ته څه ونه وایې، خو لاړ شه او خپل ځان کاهن ته وروښایه او کومه قرباني چې موسی یې حکم کړی دی وړاندې کړه، د دې دپاره چې خلکو ته ثابته شي چې ته پاک او روغ شوی یې.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark1_verse_44.mp3', '', 1761754199, 1761754199),
(36524, 'Mark 1:45', 'Mark', 1, 45, 'خو هغه سړی ووت او څه چې شوي وو ټول خلک یې پرې خبر کړل. له دې امله عیسی نور نه شو کولای چې په ښکاره کوم ښار ته ننوځي بلکې د ښار نه دباندې په ګوښه ځایونو کې به پاتې کېده، خو بیاهم خلک به له هرځای څخه ورته راتلل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark1_verse_45.mp3', '', 1761754199, 1761754199),
(36525, 'Acts 17:1', 'Acts', 17, 1, 'پولوس او سیلاس د امفیپولیس او اپولونیا د ښارونو څخه تېر شول او تسالونیکیې ته چې د یهودیانو کنیسه په کې وه، ورسېدل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts17_verse_1.mp3', '', 1761754199, 1761754199),
(36526, 'Acts 17:2', 'Acts', 17, 2, 'پولوس د خپل عادت له مخې کنیسې ته لاړ او درې هفتې یې د هر سبت په ورځ د خدای د کلام په هکله د هغوی سره بحثونه وکړل', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts17_verse_2.mp3', '', 1761754199, 1761754199),
(36527, 'Acts 17:3', 'Acts', 17, 3, 'او دا یې ورته بیان او ثابت کړل چې مسیح باید تکلیفونه وزغمي او د مړینې څخه وروسته به بیا راژوندی شي. پولوس وویل: «همدا عیسی چې زه د هغه په هکله تاسو سره خبرې کوم، هماغه مسیح دی.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts17_verse_3.mp3', '', 1761754199, 1761754199),
(36528, 'Acts 17:4', 'Acts', 17, 4, 'ځینې یهودیان او زیات شمېر دینداره یونانیان او نامتو ښځې قانع شوې او پولوس او سیلاس سره یوځای شول.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts17_verse_4.mp3', '', 1761754199, 1761754199),
(36529, 'Acts 17:5', 'Acts', 17, 5, 'خو په دې کار د ځینو یهودیانو سره بخیلي راپیدا شوه. هغوی څو بېکاره او لوچک خلک د کوڅو څخه راټول کړل او یوه ډله یې جوړه کړه او په ښار کې یې شور او غوغا جوړه کړه. هغوی د یاسون په کور حمله وکړه او کوښښ یې کاوه چې پولوس او سیلاس پیدا کړي او خلکو ته یې راولي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts17_verse_5.mp3', '', 1761754199, 1761754199),
(36530, 'Acts 17:6', 'Acts', 17, 6, 'خو چې کله یې هغوی پیدا نه کړل، نو یاسون او ځینې نور ایمانداران یې د ښار واکمنانو ته په راښکلو راوستل او چیغې یې وهلې: «دې خلکو نړۍ په بل مخ اړولې ده او اوس دلته راغلي', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts17_verse_6.mp3', '', 1761754199, 1761754199),
(36531, 'Acts 17:7', 'Acts', 17, 7, 'او یاسون هغوی په خپل کور کې مېلمانه کړي دي. دوی ټولو د امپراتور قانون مات کړی او وایي چې دلته یو بل پاچا دی چې عیسی نومیږي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts17_verse_7.mp3', '', 1761754199, 1761754199),
(36532, 'Acts 17:8', 'Acts', 17, 8, 'کله چې خلکو او د ښار واکمنانو دا خبرې واورېدلې، نو ډېر نا‌ارامه شول.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts17_verse_8.mp3', '', 1761754199, 1761754199),
(36533, 'Acts 17:9', 'Acts', 17, 9, 'نو هغوی د یاسون او نورو ایماندارانو څخه ضمانت واخیست او هغوی یې پرېښودل چې لاړ شي. پولوس او سیلاس په بیریه کې', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts17_verse_9.mp3', '', 1761754199, 1761754199),
(36534, 'Acts 17:10', 'Acts', 17, 10, 'څنګه چې شپه شوه، نو ایماندارانو پولوس او سیلاس بیریې ته ولېږل. کله چې هلته ورسېدل، نو د یهودیانو کنیسې ته لاړل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts17_verse_10.mp3', '', 1761754199, 1761754199),
(36535, 'Acts 17:11', 'Acts', 17, 11, 'د بیریې یهودیان د تسالونیکیې د یهودیانو څخه د روښانه فکر خاوندان وو. ځکه چې هغوی په ډېر شوق سره پیغام ومنلو او هره ورځ به یې په غور سره د خدای کلام لوسته، ترڅو په دې پوه شي چې کوم څه چې پولوس وایي هغه رښتیا دي که نه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts17_verse_11.mp3', '', 1761754199, 1761754199),
(36536, 'Acts 17:12', 'Acts', 17, 12, 'نو له همدې امله په هغوی کې ډېرو خلکو ایمان راوړ او همدارنګه ډېرو نامتو یوناني ښځو او سړیو هم ایمان راوړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts17_verse_12.mp3', '', 1761754199, 1761754199),
(36537, 'Acts 17:13', 'Acts', 17, 13, 'خو کله چې د تسالونیکیې یهودیان خبر شول چې پولوس په بیریه کې هم د خدای کلام بیانوي، نو هلته راغلل چې خلک ولمسوي او د پولوس په خلاف یې راپورته کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts17_verse_13.mp3', '', 1761754199, 1761754199),
(36538, 'Acts 17:14', 'Acts', 17, 14, 'نو ایماندارانو سمدلاسه پولوس د بحیرې غاړې ته ولېږه، خو سیلاس او تیموتاوس په بیریه کې پاتې شول.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts17_verse_14.mp3', '', 1761754199, 1761754199),
(36539, 'Acts 17:15', 'Acts', 17, 15, 'کومو خلکو چې پولوس یې بدرګه کاوه، د هغه سره د آتن تر ښاره پورې لاړل. بیا پولوس هغوی ته لارښوونه وکړه چې کله بېرته خپل کور ته ورسېدلئ، نو سیلاس او تیموتاوس ته ووایئ چې زر تر ژره آتن ته راشي. پولوس په آتن کې', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts17_verse_15.mp3', '', 1761754199, 1761754199),
(36540, 'Acts 17:16', 'Acts', 17, 16, 'په هغه وخت کې چې پولوس په آتن کې د سیلاس او تیموتاوس دپاره انتظار کاوه، نو کله چې هغه ولیدل چې هغه ښار د بتانو څخه ډک دی، ډېر خفه شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts17_verse_16.mp3', '', 1761754199, 1761754199),
(36541, 'Acts 17:17', 'Acts', 17, 17, 'هغه به په کنیسه کې د یهودیانو او دینداره غیریهودیانو سره بحثونه کول او هره ورځ به یې د ښار په بازارونو کې د هغو خلکو سره چې هلته ورسره مخامخ کېدل، هم بحثونه کول.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts17_verse_17.mp3', '', 1761754199, 1761754199),
(36542, 'Acts 17:18', 'Acts', 17, 18, 'ځینو اپیکوري او رواقي فیلسوفانو هم د هغه سره بحث کاوه. ځینو خلکو به پوښتنه کوله: «دا جاهل غواړي څه ووایي؟» نورو به ویل: «داسې ښکاري چې هغه د نورو خدایانو په هکله خبرې کوي.» دا یې ځکه وویل چې پولوس د عیسی او د قیامت په هکله زېری ورکاوه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts17_verse_18.mp3', '', 1761754199, 1761754199),
(36543, 'Acts 17:19', 'Acts', 17, 19, 'نو هغوی پولوس شورا ته چې د مریخ په غونډۍ کې وه، راوست او ویې ویل: «مونږ غواړو پوه شو چې دا نوی تعلیم چې ته یې ورکوې هغه د څه شي په هکله دی؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts17_verse_19.mp3', '', 1761754199, 1761754199),
(36544, 'Acts 17:20', 'Acts', 17, 20, 'ځینې خبرې چې ته یې کوې هغه مونږ ته حیرانوونکې ښکاري. مونږ غواړو چې د هغو په معنی پوه شو.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts17_verse_20.mp3', '', 1761754199, 1761754199),
(36545, 'Acts 17:21', 'Acts', 17, 21, '(ځکه چې د آتن خلکو او هغو پردیو خلکو چې هلته اوسېدل، دا خوښول چې خپل ټول وخت د نویو نظرونو په هکله په خبرو کولو او اورېدلو تېر کړي.)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts17_verse_21.mp3', '', 1761754199, 1761754199),
(36546, 'Acts 17:22', 'Acts', 17, 22, 'پولوس د مریخ د غونډۍ د شورا په مخکې ودرېده او ویې ویل: «ای د آتن خلکو! زه پوه شوم چې تاسو ډېر مذهبي خلک یئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts17_verse_22.mp3', '', 1761754199, 1761754199),
(36547, 'Acts 17:23', 'Acts', 17, 23, 'ځکه کله چې زه ستاسو په ښار کې ګرځېدم او ستاسو د عبادت شیانو ته مې کتل، نو د قربانۍ یو ځای مې ولیده چې پرې لیکل شوي وو: ‹د یو نامعلوم خدای دپاره.› تاسو چې د کوم شي عبادت کوئ او نه یې پېژنئ، د هغه په هکله تاسو ته خبرې کوم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts17_verse_23.mp3', '', 1761754199, 1761754199),
(36548, 'Acts 17:24', 'Acts', 17, 24, 'هغه خدای چې نړۍ او هرڅه چې په هغې کې دي، پیدا کړي دي، هغه د ځمکې او اسمان څښتن دی او د انسانانو په لاس جوړ شویو عبادتځایونو کې نه اوسیږي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts17_verse_24.mp3', '', 1761754199, 1761754199),
(36549, 'Acts 17:25', 'Acts', 17, 25, 'همدارنګه نه هغو شیانو ته کومه اړتیا لري چې انسانان یې په خپلو لاسونو هغه ته تیاروي، ځکه چې خدای په خپله انسانانو ته ژوند، ساه او هرڅه ورکوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts17_verse_25.mp3', '', 1761754199, 1761754199),
(36550, 'Acts 17:26', 'Acts', 17, 26, 'هغه ټول قومونه د یو انسان د نسل څخه پیدا کړل چې په ټولې نړۍ کې واوسیږي. د هغوی دپاره یې وختونه او د ځایونو حدونه وټاکل چې چېرته به اوسیږي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts17_verse_26.mp3', '', 1761754199, 1761754199),
(36551, 'Acts 17:27', 'Acts', 17, 27, 'د هغه مقصد دا ؤ چې هغوی د خدای په لټه کې اوسي، هغه ته ځانونه ورسوي او پیدا یې کړي، که څه هم هغه زمونږ هر یو څخه لېرې نه دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts17_verse_27.mp3', '', 1761754199, 1761754199),
(36552, 'Acts 17:28', 'Acts', 17, 28, 'لکه څنګه چې یو چا ویلي دي: په هغه کې زمونږ ژوند، زمونږ حرکت او زمونږ شتون دی. لکه څنګه چې ستاسو ځینو شاعرانو ویلي دي: مونږ هم د هغه اولادونه یو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts17_verse_28.mp3', '', 1761754199, 1761754199),
(36553, 'Acts 17:29', 'Acts', 17, 29, 'نو څرنګه چې مونږ د خدای اولادونه یو، نو باید داسې فکر ونه کړو چې د خدای ذات د یوې مجسمې په شان دی چې د انسان په هنر او مهارت د سرو زرو، سپینو زرو یا تیږو څخه جوړه شوې وي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts17_verse_29.mp3', '', 1761754199, 1761754199),
(36554, 'Acts 17:30', 'Acts', 17, 30, 'په هغه وخت کې چې خلکو خدای نه پېژانده، خدای په دې شیانو سترګې پټولې. خو اوس هغه په هرځای کې ټولو خلکو ته حکم کوي چې توبه وباسي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts17_verse_30.mp3', '', 1761754199, 1761754199),
(36555, 'Acts 17:31', 'Acts', 17, 31, 'ځکه چې خدای یوه ورځ ټاکلې ده چې هغه به د عدالت له مخې د نړۍ قضاوت د هغه چا په وسیله کوي چې هغه غوره کړی دی. او د هغه کس په بیا راژوندي کولو سره یې دا خبره ټولو خلکو ته ثابته کړې ده.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts17_verse_31.mp3', '', 1761754199, 1761754199),
(36556, 'Acts 17:32', 'Acts', 17, 32, 'کله چې هغوی د پولوس څخه د مړو نه د راژوندي کېدلو خبره واورېدله، نو ځینو ورباندې ملنډې ووهلې، خو نورو وویل: «مونږ به په دې هکله په کوم بل وخت کې ستا خبرې بیا واورو.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts17_verse_32.mp3', '', 1761754199, 1761754199),
(36557, 'Acts 17:33', 'Acts', 17, 33, 'نو په دې ډول پولوس د هغوی څخه لاړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts17_verse_33.mp3', '', 1761754199, 1761754199),
(36558, 'Acts 17:34', 'Acts', 17, 34, 'خو یو څو تنه د پولوس سره یوځای شول او ایمان یې راوړ، چې دیونیسوس چې د مریخ د غونډۍ د شورا غړی ؤ او همدارنګه یوه ښځه چې دامریس نومېدله او ځینې نور خلک هم ورسره وو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts17_verse_34.mp3', '', 1761754199, 1761754199),
(36559, 'Acts 20:1', 'Acts', 20, 1, 'کله چې شور او غوغا پای ته ورسېدله، نو پولوس ایمانداران راوغوښتل، هغوی یې وهڅول او خدای پاماني یې ورسره وکړه او مقدونیې ته روان شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts20_verse_1.mp3', '', 1761754199, 1761754199),
(36560, 'Acts 20:2', 'Acts', 20, 2, 'هغه د مقدونیې د سیمو له لارې تېرېده او ایماندارانو ته یې ډاډګېرنه ورکوله او بیا یونان ته ورسېده.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts20_verse_2.mp3', '', 1761754199, 1761754199),
(36561, 'Acts 20:3', 'Acts', 20, 3, 'درې میاشتې هلته پاتې شو. هغه تیاری ونیوه چې په کشتۍ کې سوریې ته لاړ شي، خو کله چې پوه شو چې یهودیانو د هغه په خلاف دسیسه جوړه کړې ده، نو پرېکړه یې وکړه چې د مقدونیې په لاره بېرته ستون شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts20_verse_3.mp3', '', 1761754199, 1761754199),
(36562, 'Acts 20:4', 'Acts', 20, 4, 'د پیروس زوی سوپاتروس چې د بیریې څخه ؤ، ارسترخوس او سکندوس د تسالونیکې څخه، ګایوس له دربې څخه، تیخیکاس او تروفیموس چې د اسیا د ولایت څخه او تیموتاوس د هغه د سفر ملګري وو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts20_verse_4.mp3', '', 1761754199, 1761754199),
(36563, 'Acts 20:5', 'Acts', 20, 5, 'هغوی مخکې لاړل او په ترواس کې یې زمونږ انتظار کاوه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts20_verse_5.mp3', '', 1761754199, 1761754199),
(36564, 'Acts 20:6', 'Acts', 20, 6, 'کله چې د فطیرې ډوډۍ د اختر ورځې تېرې شوې، نو مونږ د فیلیپیې څخه په کشتۍ کې روان شولو او په پنځو ورځو کې د هغوی سره په ترواس کې یوځای شولو او یوه هفته هلته پاتې شولو. په ترواس کې د پولوس وروستنۍ لیدنه او کتنه', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts20_verse_6.mp3', '', 1761754199, 1761754199),
(36565, 'Acts 20:7', 'Acts', 20, 7, 'د شنبې ورځې په ماښام مونږ د غوره ماښامي د مراسمو د لمانځلو دپاره سره راټول شولو. پولوس ایماندارانو ته خبرې وکړې، څرنګه چې هغه غوښتل بله ورځ په سفر لاړ شي، نو تر نیمې شپې پورې یې خپلو خبرو ته دوام ورکړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts20_verse_7.mp3', '', 1761754199, 1761754199),
(36566, 'Acts 20:8', 'Acts', 20, 8, 'پاس په بالاخانه کې چې مونږ په کې راټول شوي وو، ډېر څراغونه لګېدلي وو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts20_verse_8.mp3', '', 1761754199, 1761754199),
(36567, 'Acts 20:9', 'Acts', 20, 9, 'هلته په کړکۍ کې یو ځوان ناست ؤ چې افتیخوس نومېده. کله چې پولوس خبرې کولې، نو په هغه ځوان باندې خوب راغی او په درانه خوب ویده شو او د درېم منزل څخه لاندې ځمکې ته راولوېد. کله یې چې راپورته کړ، نو هغه مړ شوی ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts20_verse_9.mp3', '', 1761754199, 1761754199),
(36568, 'Acts 20:10', 'Acts', 20, 10, 'پولوس لاندې ورښکته شو او خپل ځان یې په هغه ځوان باندې وروغورځاوه او هغه یې په غېږ کې ونیوه او هغوی ته یې وویل: «مه پرېشانه کېږئ، هغه ژوندی دی.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts20_verse_10.mp3', '', 1761754199, 1761754199),
(36569, 'Acts 20:11', 'Acts', 20, 11, 'بیا پولوس بېرته بالاخانې ته وخوت، ډوډۍ یې ماته کړه او ویې خوړله. هغه تر لمرخاته پورې د هغوی سره خبرو ته دوام ورکړ او بیا روان شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts20_verse_11.mp3', '', 1761754199, 1761754199),
(36570, 'Acts 20:12', 'Acts', 20, 12, 'بیا خلکو هغه ځوان خپل کور ته ژوندی بوته او هغوی ډېر ارام شول. د ترواس څخه میلیتوس ته د پولوس سفر', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts20_verse_12.mp3', '', 1761754199, 1761754199),
(36571, 'Acts 20:13', 'Acts', 20, 13, 'مونږ مخکې لاړو او په کشتۍ کې کښېناستو او د اسوس ښار ته روان شولو، چېرته چې مونږ غوښتل پولوس هم راسره په کشتۍ کې سپور شي. ځکه چې هغه نیت کړی ؤ چې د وچې لارې نه هغه ځای ته لاړ شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts20_verse_13.mp3', '', 1761754199, 1761754199),
(36572, 'Acts 20:14', 'Acts', 20, 14, 'کله چې پولوس په اسوس کې زمونږ سره مخامخ شو، نو هغه مو په کشتۍ کې سپور کړ او میتیلینې ته راغلو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts20_verse_14.mp3', '', 1761754199, 1761754199),
(36573, 'Acts 20:15', 'Acts', 20, 15, 'د هغه ځای څخه په کشتۍ کې روان شو او په بله ورځ د خیوس جزیرې ته ورسېدلو. بله ورځ ساموس ته راغلو او د هغې ورځې په سبا میلیتوس ته ورسېدلو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts20_verse_15.mp3', '', 1761754199, 1761754199),
(36574, 'Acts 20:16', 'Acts', 20, 16, 'ځکه چې پولوس پرېکړه کړې وه چې په کشتۍ کې د افسیس څخه تېر شي، ترڅو د اسیا په ولایت کې د وخت د ضایع کېدلو څخه مخنیوی وشي. هغه بیړه کوله چې که چېرې امکان ولري د پنتیکاست د ورځې نه مخکې اورشلیم ته ورسیږي. د افسیس د کلیسا د مشرانو سره د پولوس خدای پاماني', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts20_verse_16.mp3', '', 1761754199, 1761754199),
(36575, 'Acts 20:17', 'Acts', 20, 17, 'پولوس د میلیتوس څخه افسیس ته پیغام ولېږه او د کلیسا د مشرانو څخه یې وغوښتل چې راشي او د هغه سره وویني.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts20_verse_17.mp3', '', 1761754199, 1761754199),
(36576, 'Acts 20:18', 'Acts', 20, 18, 'کله چې هغوی راورسېدل، نو هغه ورته وویل: «تاسو ته معلومه ده چې د هماغې لومړۍ ورځې څخه چې زه د اسیا ولایت ته راورسېدم او څومره وخت چې ستاسو سره وم، نو تاسو سره مې څنګه ژوند تېر کړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts20_verse_18.mp3', '', 1761754199, 1761754199),
(36577, 'Acts 20:19', 'Acts', 20, 19, 'که څه هم د یهودیانو د دسیسو له امله په ما سختې ورځې راغلې، خو ما په پوره عاجزۍ او اوښکو تویولو سره د څښتن خدمت کړی دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts20_verse_19.mp3', '', 1761754199, 1761754199),
(36578, 'Acts 20:20', 'Acts', 20, 20, 'تاسو ته معلومه ده چې ما ستاسو د ښېګڼې دپاره د هېڅ شي څخه ډډه نه ده کړې او تاسو ته مې د خلکو په مخکې او کور په کور تعلیم درکړی دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts20_verse_20.mp3', '', 1761754199, 1761754199),
(36579, 'Acts 20:21', 'Acts', 20, 21, 'ما یهودیانو او غیریهودیانو دواړو ته په کلکه خبرداری ورکړ چې باید د خپلو ګناهونو څخه توبه وباسي او خدای ته رجوع وکړي او زمونږ په څښتن عیسی ایمان راوړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts20_verse_21.mp3', '', 1761754199, 1761754199),
(36580, 'Acts 20:22', 'Acts', 20, 22, 'زه اوس د روح القدس څخه په اطاعت کولو سره اورشلیم ته روان یم، خو نه پوهېږم چې هلته به زما سره څه کیږي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts20_verse_22.mp3', '', 1761754199, 1761754199),
(36581, 'Acts 20:23', 'Acts', 20, 23, 'زه یوازې په دې پوهېږم چې روح القدس په هر ښار کې ما خبروي چې زندان او تکلیفونه زما په انتظار کې دي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts20_verse_23.mp3', '', 1761754199, 1761754199),
(36582, 'Acts 20:24', 'Acts', 20, 24, 'خو زه د خپل ژوند هېڅ پروا نه لرم او هغه ماته کوم ارزښت نه لري. زه یوازې دا غواړم چې خپله وظیفه سرته ورسوم کومه چې څښتن عیسی راته سپارلې ده، هغه تر‌سره کړم چې هغه د خدای د فضل په هکله د خلکو خبرول دي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts20_verse_24.mp3', '', 1761754199, 1761754199),
(36583, 'Acts 20:25', 'Acts', 20, 25, 'زه ستاسو ټولو په منځ کې ګرځېدلی یم او د خدای د پاچاهۍ په هکله مې وعظ کړی دی. اوس پوهېږم چې ستاسو څخه به یو کس هم نور زما مخ ونه ویني.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts20_verse_25.mp3', '', 1761754199, 1761754199),
(36584, 'Acts 20:26', 'Acts', 20, 26, 'نو له دې امله زه همدا‌نن تاسو خبروم چې که ستاسو څخه کوم څوک د تلپاتې ژوندون څخه بې‌برخې شي، نو زه به یې مسوول نه یم،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts20_verse_26.mp3', '', 1761754199, 1761754199),
(36585, 'Acts 20:27', 'Acts', 20, 27, 'ځکه چې ما تاسو ته هغه ټول شیان وویل چې خدای یې غواړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts20_verse_27.mp3', '', 1761754199, 1761754199),
(36586, 'Acts 20:28', 'Acts', 20, 28, 'په خپلو ځانونو او هغو ټولو خلکو باندې پام کوئ چې روح القدس تاسو د هغو د ساتنې دپاره ټاکلي یئ. د خدای په کلیسا باندې چې عیسی د خپلې وینې په بیه اخیستې ده، داسې پام کوئ لکه څنګه چې شپانه په خپلو رمو پام کوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts20_verse_28.mp3', '', 1761754199, 1761754199),
(36587, 'Acts 20:29', 'Acts', 20, 29, 'زه پوهېږم چې زما د تګ څخه وروسته به داړونکي لېوان ستاسو منځ ته درشي او رمه به په امان کې پرېنږدي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts20_verse_29.mp3', '', 1761754199, 1761754199),
(36588, 'Acts 20:30', 'Acts', 20, 30, 'حتی ستاسو په منځ کې به داسې خلک پیدا شي چې د حقیقت په ځای به دروغ وایي، ترڅو ایمانداران خپل ځان ته راواړوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts20_verse_30.mp3', '', 1761754199, 1761754199),
(36589, 'Acts 20:31', 'Acts', 20, 31, 'نو بېداره اوسئ او دا خبره یاد ساتئ چې درې کاله مې شپه او ورځ تاسو هر یو ته نصیحت کاوه او ستاسو دپاره مې اوښکې تویې کړې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts20_verse_31.mp3', '', 1761754199, 1761754199),
(36590, 'Acts 20:32', 'Acts', 20, 32, 'اوس زه تاسو خدای او د هغه د فضل نه ډک کلام ته سپارم، هغه کلام ته چې کولای شي تاسو ته قوت درکړي او هغه برکتونه درکړي چې خدای یې خپلو ټولو سپېڅلو خلکو د میراث په توګه ورکوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts20_verse_32.mp3', '', 1761754199, 1761754199),
(36591, 'Acts 20:33', 'Acts', 20, 33, 'ما هېڅکله د چا نه د سپینو زرو، سرو زرو او کالیو تمه نه ده کړې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts20_verse_33.mp3', '', 1761754199, 1761754199),
(36592, 'Acts 20:34', 'Acts', 20, 34, 'تاسو خپله پوهېږئ چې ما په خپلو لاسونو زیار ویستلی او د خپل ځان او خپلو ملګرو اړتیاوې مې پوره کړې دي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts20_verse_34.mp3', '', 1761754199, 1761754199),
(36593, 'Acts 20:35', 'Acts', 20, 35, 'ما په خپلو سختو کارونو سره تاسو ته وښودل چې په دې ډول کولای شو چې د غریبانو سره مرسته وکړو او باید د څښتن عیسی هغه خبرې په یاد وساتو چې ویلي یې دي: ‹د اخیستلو څخه په ورکولو کې برکتونه ډېر دي.›»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts20_verse_35.mp3', '', 1761754199, 1761754199),
(36594, 'Acts 20:36', 'Acts', 20, 36, 'کله چې پولوس خپلې خبرې پای ته ورسولې، نو د هغوی سره یوځای په ګونډو شو او د هغوی ټولو سره یې دعا وکړه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts20_verse_36.mp3', '', 1761754199, 1761754199),
(36595, 'Acts 20:37', 'Acts', 20, 37, 'بیا هغوی ټولو وژړل، هغه یې په غېږ کې ونیوه، ښکل یې کړ او خدای پاماني یې ورسره وکړه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts20_verse_37.mp3', '', 1761754199, 1761754199),
(36596, 'Acts 20:38', 'Acts', 20, 38, 'هغوی په دې ډېر زیات غمجن شول، ځکه چې پولوس ویلي وو چې دوی به نور هېڅکله د هغه مخ ونه ویني. نو هغوی ورسره تر کشتۍ پورې لاړل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts20_verse_38.mp3', '', 1761754199, 1761754199),
(36597, 'Ephesians 1:1', 'Ephesians', 1, 1, 'دا لیک د پولوس له خوا چې د خدای په ارادې د عیسی مسیح رسول دی، د خدای هغو خلکو ته چې د افسیس په ښار کې دي او عیسی مسیح ته وفادار دي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians1_verse_1.mp3', '', 1761754199, 1761754199),
(36598, 'Ephesians 1:2', 'Ephesians', 1, 2, 'زمونږ د پلار خدای او څښتن عیسی مسیح فضل او سلامتي دې وي په تاسو باندې. په مسیح کې روحاني برکتونه', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians1_verse_2.mp3', '', 1761754199, 1761754199),
(36599, 'Ephesians 1:3', 'Ephesians', 1, 3, 'ثنا او صفت دې وي خدای ته یعنې زمونږ د څښتن عیسی مسیح پلار ته چې مونږ ته یې په مسیح کې په اسماني ځایونو کې هر ډول روحاني برکتونه راکړي دي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians1_verse_3.mp3', '', 1761754199, 1761754199),
(36600, 'Ephesians 1:4', 'Ephesians', 1, 4, 'ځکه چې هغه مونږ د دنیا د پیدایښت نه مخکې په مسیح کې غوره کړو، ترڅو د هغه په نظر کې سپېڅلي او بې‌عیبه واوسو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians1_verse_4.mp3', '', 1761754199, 1761754199),
(36601, 'Ephesians 1:5', 'Ephesians', 1, 5, 'د خپلې ارادې او خوښې له مخې یې په مینه د مخکې نه پرېکړه کړې ده چې د عیسی مسیح په وسیله مونږ د خپلو اولادونو په توګه قبول کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians1_verse_5.mp3', '', 1761754199, 1761754199),
(36602, 'Ephesians 1:6', 'Ephesians', 1, 6, 'خدای داسې وکړل، ترڅو مونږ ته د هغه د جلال نه ډک فضل دپاره چې مونږ ته یې په خپل ګران زوی کې په سخاوتمندانه توګه راکړی دی، ثنا ووایو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians1_verse_6.mp3', '', 1761754199, 1761754199),
(36603, 'Ephesians 1:7', 'Ephesians', 1, 7, 'د هغه د ډېر زیات فضل له مخې مونږ په هغه کې د هغه د زوی د وینې په وسیله خلاصون وموند، یعنې سرغړونې مو وبخښل شوې،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians1_verse_7.mp3', '', 1761754199, 1761754199),
(36604, 'Ephesians 1:8', 'Ephesians', 1, 8, 'چې هغه په ټول حکمت او پوهې سره په پرېمانه توګه مونږ ته راکړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians1_verse_8.mp3', '', 1761754199, 1761754199),
(36605, 'Ephesians 1:9', 'Ephesians', 1, 9, 'خدای مونږ ته د خپلې ارادې پټ راز ښکاره کړ او د خپلې خوښې له مخې یې د عیسی مسیح په وسیله دا مقصد پوره کړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians1_verse_9.mp3', '', 1761754199, 1761754199),
(36606, 'Ephesians 1:10', 'Ephesians', 1, 10, 'دا نقشه به په یو سم وخت کې پوره کیږي چې هغه ټول شیان که په اسمان کې دي یا په ځمکه کې د مسیح د واک او اختیار لاندې سره یوځای شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians1_verse_10.mp3', '', 1761754199, 1761754199),
(36607, 'Ephesians 1:11', 'Ephesians', 1, 11, 'خدای چې هرڅه د خپلې ارادې او مقصد له مخې سرته رسوي، مونږ یې غوره کړو چې په مسیح کې د هغه خپل خلک واوسو، ځکه چې مونږ یې د مخکې نه د خپلې ارادې له مخې غوره کړي وو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians1_verse_11.mp3', '', 1761754199, 1761754199),
(36608, 'Ephesians 1:12', 'Ephesians', 1, 12, 'نو بیا مونږ چې لومړني خلک وو چې مسیح ته هیله‌من شولو، باید د هغه د جلال او لویۍ ثنا او صفت وکړو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians1_verse_12.mp3', '', 1761754199, 1761754199),
(36609, 'Ephesians 1:13', 'Ephesians', 1, 13, 'تاسو هم چې کله رښتینی کلام یعنې خپل د خلاصون زېری واورېد او په هغه باندې مو ایمان راوړ، نو خدای تاسو ته د روح القدس په درکولو سره چې مخکې یې وعده کړې وه، په تاسو باندې د خپل ملکیت مهر ولګاوه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians1_verse_13.mp3', '', 1761754199, 1761754199),
(36610, 'Ephesians 1:14', 'Ephesians', 1, 14, 'همدا روح دی چې د خدای له خوا مونږ ته د هغه د میراث ضمانت دی چې مونږ به یې تر‌لاسه کوو. خدای مونږ په بیه واخیستلو چې د هغه خلک واوسو، ترڅو د هغه د جلال او لویۍ صفت وشي. د پولوس رسول دعا', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/ephesians1_verse_14.mp3', '', 1761754199, 1761754199);